DELIMITER $$
--
-- Procedimientos
--
CREATE DEFINER=`root`@`localhost` PROCEDURE `seed_messages` ()   BEGIN
  DECLARE i INT DEFAULT 1;

  WHILE i <= 1000 DO
    INSERT INTO messages (id_chat, sender_id, created_at, message)
    VALUES (
      27,
      IF(MOD(i,2)=0, 34, 76),
      TIMESTAMP('2026-02-24') + INTERVAL FLOOR(RAND()*86400) SECOND,
      CONCAT('Mensaje de prueba número ', i)
    );

    SET i = i + 1;
  END WHILE;
END$$

CREATE DEFINER=`root`@`localhost` PROCEDURE `seed_users` ()   BEGIN
  DECLARE i INT DEFAULT 1;

  WHILE i <= 150 DO
    INSERT INTO users
    (name, email, password, photo, rol, status, online, view_online, visibility, notification, first_login)
    VALUES
    (
      CONCAT('Usuario ', i),
      CONCAT('usuario', i, '@mail.com'),
      '8d969eef6ecad3c29a3a629280e686cf0c3f5d5a86aff3ca12020c923adc6c92',
      CONCAT('https://ui-avatars.com/api/?name=Usuario+', i, '&background=random&color=fff'),
      2,
      0,
      0,
      1,
      1,
      1,
      1
    );

    SET i = i + 1;
  END WHILE;
END$$

